const __aivicBundle_3_calculateFoodRatingPriority = (() => {
  interface CalculateFoodRatingPriorityInput {
    dish_id: string;
    dish_name: string;
    rating_data: Array<{
      dish_id: string;
      dish_name: string;
      family_member_id: string;
      satisfaction_score: number;
      evaluation_datetime: Date;
    }>;
  }
  
  interface CalculateFoodRatingPriorityOutput {
    priority_score: number;
    total_evaluations: number;
    high_rating_count: number;
    low_rating_count: number;
  }
  
   function calculateFoodRatingPriority(
    input: CalculateFoodRatingPriorityInput
  ): CalculateFoodRatingPriorityOutput {
    const { rating_data } = input;
  
    if (!rating_data || rating_data.length === 0) {
      return {
        priority_score: 0,
        total_evaluations: 0,
        high_rating_count: 0,
        low_rating_count: 0,
      };
    }
  
    const total_evaluations = rating_data.length;
    let sum_satisfaction = 0;
    let high_rating_count = 0;
    let low_rating_count = 0;
  
    for (const evaluation of rating_data) {
      const score = evaluation.satisfaction_score;
      sum_satisfaction += score;
  
      if (score >= 4) {
        high_rating_count++;
      } else if (score <= 2) {
        low_rating_count++;
      }
    }
  
    const priority_score = sum_satisfaction / total_evaluations;
  
    return {
      priority_score,
      total_evaluations,
      high_rating_count,
      low_rating_count,
    };
  }
  return { calculateFoodRatingPriority };
})();
