const __aivicBundle_4_reflectRatingInMenuGeneration = (() => {
  function reflectRatingInMenuGeneration(input: {
    user_id: string;
    family_id: string;
    target_date: Date;
    dish_priorities: Array<{
      priority_score: number;
      total_evaluations: number;
      high_rating_count: number;
      low_rating_count: number;
      dish_id?: string;
      dish_name?: string;
    }>;
    dietary_restrictions: Array<{
      restriction_id: string;
      restriction_type: string;
      ingredient: string;
      severity: string;
    }>;
    allergy_info: Array<{
      allergen_id: string;
      allergen_name: string;
      severity: string;
    }>;
  }): {
    menu_items: Array<{
      dish_id: string;
      inclusion_priority: number;
      dish_name: string;
    }>;
    total_items: number;
  } {
    if (input["user_id"] === undefined || input["user_id"] === null) { throw new Error("user_id is required"); }
    if (input["family_id"] === undefined || input["family_id"] === null) { throw new Error("family_id is required"); }
    if (input["target_date"] === undefined || input["target_date"] === null) { throw new Error("target_date is required"); }
    if (input.user_id === undefined || input.user_id === null || String(input.user_id).trim() === "") {
      throw new Error("user_id is required");
    }
    if (input.family_id === undefined || input.family_id === null || String(input.family_id).trim() === "") {
      throw new Error("family_id is required");
    }
    if (input.target_date === undefined || input.target_date === null) {
      throw new Error("target_date is required");
    }
  
    const menu_items: Array<{
      dish_id: string;
      inclusion_priority: number;
      dish_name: string;
    }> = [];
  
    if (!input.dish_priorities || input.dish_priorities.length === 0) {
      return {
        menu_items: [],
        total_items: 0,
      };
    }
  
    const allergen_names = new Set(
      input.allergy_info.map((a) => a.allergen_name.toLowerCase())
    );
    const restricted_ingredients = new Set(
      input.dietary_restrictions.map((r) => r.ingredient.toLowerCase())
    );
  
    for (const dish_priority of input.dish_priorities) {
      const dish_id = dish_priority.dish_id || randomUUID();
      const dish_name = dish_priority.dish_name || "Unknown Dish";
      const priority_score = dish_priority.priority_score;
  
      const is_constrained =
        allergen_names.size > 0 || restricted_ingredients.size > 0;
  
      if (is_constrained) {
        const allergen_match = Array.from(allergen_names).some((allergen) =>
          dish_name.toLowerCase().includes(allergen)
        );
        const restriction_match = Array.from(restricted_ingredients).some(
          (ingredient) => dish_name.toLowerCase().includes(ingredient)
        );
  
        if (allergen_match || restriction_match) {
          continue;
        }
      }
  
      menu_items.push({
        dish_id,
        inclusion_priority: priority_score,
        dish_name,
      });
    }
  
    return {
      menu_items,
      total_items: menu_items.length,
    };
  }
  return { reflectRatingInMenuGeneration };
})();
export const reflectRatingInMenuGeneration = __aivicBundle_4_reflectRatingInMenuGeneration.reflectRatingInMenuGeneration;
