const __aivicBundle_25_detectAnomaliesInMealEvaluations = (() => {
  function detectAnomaliesInMealEvaluations(
    aggregated_evaluations: Array<{
      meal_id: string;
      family_member_id: string;
      satisfaction_score: number;
      completion_rate: number;
      request: string | null;
      timestamp: string;
    }>
  ): {
    has_anomalies: boolean;
    trust_score: number;
    filtered_evaluations: Array<{
      meal_id: string;
      family_member_id: string;
      satisfaction_score: number;
      completion_rate: number;
      request: string | null;
      timestamp: string;
    }>;
    anomaly_flags: string[];
  } {
    const SATISFACTION_MIN = 1;
    const SATISFACTION_MAX = 5;
    const COMPLETION_MIN = 0;
    const COMPLETION_MAX = 100;
  
    const filtered_evaluations: Array<{
      meal_id: string;
      family_member_id: string;
      satisfaction_score: number;
      completion_rate: number;
      request: string | null;
      timestamp: string;
    }> = [];
    const anomaly_flags_set = new Set<string>();
    let validCount = 0;
  
    for (const evaluation of aggregated_evaluations) {
      const anomalies: string[] = [];
  
      if (
        evaluation.satisfaction_score < SATISFACTION_MIN ||
        evaluation.satisfaction_score > SATISFACTION_MAX
      ) {
        anomalies.push("score_out_of_range");
      }
  
      if (
        evaluation.completion_rate < COMPLETION_MIN ||
        evaluation.completion_rate > COMPLETION_MAX
      ) {
        anomalies.push("completion_rate_out_of_range");
      }
  
      if (
        evaluation.satisfaction_score > 3 &&
        evaluation.completion_rate < 20
      ) {
        anomalies.push("contradictory_satisfaction_completion");
      }
  
      if (anomalies.length === 0) {
        filtered_evaluations.push(evaluation);
        validCount++;
      } else {
        anomalies.forEach((flag) => anomaly_flags_set.add(flag));
      }
    }
  
    const has_anomalies = anomaly_flags_set.size > 0;
    let trust_score = 1.0;
  
    if (aggregated_evaluations.length > 0) {
      trust_score = validCount / aggregated_evaluations.length;
      trust_score = Math.max(0.0, Math.min(1.0, trust_score));
    }
  
    return {
      has_anomalies,
      trust_score,
      filtered_evaluations,
      anomaly_flags: Array.from(anomaly_flags_set),
    };
  }
  return { detectAnomaliesInMealEvaluations };
})();
