/* AIVIC_FUNCTION_BUNDLE_START owner=selectRolloutSegments exports=selectRolloutSegments */
const __aivicBundle_32_selectRolloutSegments = (() => {
  function selectRolloutSegments(input: {
    segmentId?: string;
    ageGroup?: string;
    familySize?: number;
    hasRestriction?: boolean;
    adoptionRate?: number;
    satisfactionScore?: number;
    cookingTimeReduction?: number;
  }): {
    status: string;
    rolloutOrder: number;
    targetUserCount: number;
    rolloutExecuted: boolean;
  } {
    // Validation: segmentId
    if (!input.segmentId || input.segmentId === '') {
      throw new Error('セグメントIDが未定義または空です');
    }
  
    // Validation: ageGroup
    if (!input.ageGroup || input.ageGroup === '') {
      throw new Error('年代情報が未定義または空です');
    }
  
    // Validation: familySize
    if (input.familySize === null || input.familySize === undefined || input.familySize <= 0) {
      throw new Error('家族構成が不正です');
    }
  
    // Validation: hasRestriction (must be boolean)
    if (typeof input.hasRestriction !== 'boolean') {
      throw new Error('食事制限フラグが不正な型です');
    }
  
    // Validation: adoptionRate (0 <= x <= 1)
    if (input.adoptionRate === undefined || input.adoptionRate < 0 || input.adoptionRate > 1) {
      throw new Error('採用率が範囲外です');
    }
  
    // Validation: satisfactionScore (0 <= x <= 100)
    if (input.satisfactionScore === undefined || input.satisfactionScore < 0 || input.satisfactionScore > 100) {
      throw new Error('満足度スコアが範囲外です');
    }
  
    // Validation: cookingTimeReduction (>= 0)
    if (input.cookingTimeReduction === undefined || input.cookingTimeReduction < 0) {
      throw new Error('調理時間削減量が負数です');
    }
  
    // Calculate rolloutOrder based on satisfaction score and adoption rate
    // Higher satisfaction and adoption → lower order (higher priority)
    const combinedScore = (input.satisfactionScore / 100) * 0.6 + input.adoptionRate * 0.4;
    let rolloutOrder: number;
    if (combinedScore >= 0.8) {
      rolloutOrder = 1;
    } else if (combinedScore >= 0.65) {
      rolloutOrder = 2;
    } else if (combinedScore >= 0.5) {
      rolloutOrder = 3;
    } else if (combinedScore >= 0.35) {
      rolloutOrder = 4;
    } else {
      rolloutOrder = 5;
    }
  
    // Calculate targetUserCount based on familySize and restriction flag
    // Segments with restrictions may have smaller target pools
    const baseUserCount = Math.max(10, Math.floor(100 / input.familySize));
    const targetUserCount = input.hasRestriction ? Math.floor(baseUserCount * 0.8) : baseUserCount;
  
    return {
      status: 'success',
      rolloutOrder,
      targetUserCount: Math.max(1, targetUserCount),
      rolloutExecuted: true,
    };
  }
  return { selectRolloutSegments };
})();
export const selectRolloutSegments = __aivicBundle_32_selectRolloutSegments.selectRolloutSegments;
/* AIVIC_FUNCTION_BUNDLE_END owner=selectRolloutSegments */

