const __aivicBundle_49_prioritizeNutrientDeficiencyItems = (() => {
  function prioritizeNutrientDeficiencyItems(
    nutrientDeficiencies: Array<{
      nutrientId: string;
      deficiencyAmount: number;
      improvementEffectScore: number;
    }>,
    familyMemberPreferences: Array<{
      familyMemberId: string;
      preferenceScore: number;
    }>,
    preferenceRiskCoefficient: number | null | undefined
  ): Array<{
    nutrientId: string;
    deficiencyAmount: number;
    improvementEffectScore: number;
    priorityScore: number;
  }> {
    if (
      preferenceRiskCoefficient === null ||
      preferenceRiskCoefficient === undefined
    ) {
      throw new Error("嗜好リスク係数が無効です");
    }
  
    if (preferenceRiskCoefficient < 0 || preferenceRiskCoefficient > 1.0) {
      throw new Error("嗜好リスク係数は0以上1.0以下である必要があります");
    }
  
    const averagePreferenceScore =
      familyMemberPreferences.length > 0
        ? familyMemberPreferences.reduce((sum, pref) => sum + pref.preferenceScore, 0) /
          familyMemberPreferences.length
        : 0.5;
  
    const prioritized = nutrientDeficiencies.map((deficiency) => {
      const basePriority = deficiency.improvementEffectScore;
      const deficiencyWeighting = deficiency.deficiencyAmount > 0 ? 1 : 0.5;
      const preferenceAdjustment =
        1 + preferenceRiskCoefficient * (averagePreferenceScore - 0.5);
  
      const priorityScore =
        basePriority * deficiencyWeighting * preferenceAdjustment;
  
      return {
        nutrientId: deficiency.nutrientId,
        deficiencyAmount: deficiency.deficiencyAmount,
        improvementEffectScore: deficiency.improvementEffectScore,
        priorityScore,
      };
    });
  
    prioritized.sort((a, b) => b.priorityScore - a.priorityScore);
  
    return prioritized;
  }
  return { prioritizeNutrientDeficiencyItems };
})();
