const __aivicBundle_61_calculateDemandForecastImprovementDecision = (() => {
  function calculateDemandForecastImprovementDecision(input: {
    forecastQuantity: number;
    actualQuantity: number;
    improvementThreshold: number;
  }): {
    deviationRate: number;
    decision: string;
    isWithinThreshold: boolean;
  } {
    const { forecastQuantity, actualQuantity, improvementThreshold } = input;
  
    // 乖離率を計算（パーセンテージ）
    const deviationRate =
      Math.abs(forecastQuantity - actualQuantity) / forecastQuantity * 100;
  
    // 乖離率が閾値以内かどうかを判定
    const isWithinThreshold = deviationRate <= improvementThreshold;
  
    // 改善判定：乖離率が閾値以内なら改善見送り、超過なら改善推奨
    const decision = isWithinThreshold ? '改善見送り' : '改善推奨';
  
    return {
      deviationRate: Math.round(deviationRate),
      decision,
      isWithinThreshold,
    };
  }
  return { calculateDemandForecastImprovementDecision };
})();
