/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDemandForecastAccuracy exports=calculateDemandForecastAccuracy */
const __aivicBundle_65_calculateDemandForecastAccuracy = (() => {
  function calculateDemandForecastAccuracy(input: {
    forecast_value: number;
    actual_value: number;
  }): {
    deviation_rate_percent: number;
    improvement_decision: string;
    is_improvement_target: boolean;
    recorded_at: string;
  } {
    const { forecast_value, actual_value } = input;
  
    // 乖離率を計算（パーセンテージ）
    const deviation_rate_percent =
      forecast_value === 0
        ? 0
        : Math.abs((actual_value - forecast_value) / forecast_value) * 100;
  
    // 乖離率に基づいて改善判定を行う
    // 0%: 改善見送り（完全一致）
    // 1-10%: 改善見送り（許容範囲内）
    // 11-20%: 標準（要監視）
    // 21%以上: 改善必要
    let improvement_decision: string;
    let is_improvement_target: boolean;
  
    if (deviation_rate_percent <= 10) {
      improvement_decision = '改善見送り';
      is_improvement_target = false;
    } else if (deviation_rate_percent <= 20) {
      improvement_decision = '標準';
      is_improvement_target = false;
    } else {
      improvement_decision = '改善必要';
      is_improvement_target = true;
    }
  
    // 現在時刻を ISO 8601 形式で取得
    const recorded_at = new Date().toISOString();
  
    return {
      deviation_rate_percent,
      improvement_decision,
      is_improvement_target,
      recorded_at,
    };
  }
  return { calculateDemandForecastAccuracy };
})();
