const __aivicBundle_82_calculateIngredientsSeasonalPriorityScores = (() => {
  function calculateIngredientsSeasonalPriorityScores(
    ingredients: any[],
    discountData: any[],
    currentDate: Date
  ): any[] {
    if (!ingredients || ingredients.length === 0) {
      return [];
    }
  
    const currentMonth = currentDate.getMonth() + 1;
    const discountMap = new Map<string, { rate: number; startDate: Date; endDate: Date }>();
  
    if (discountData && Array.isArray(discountData)) {
      for (const discount of discountData) {
        const ingredientId = discount.ingredient_id || discount.ingredientId;
        const rate = discount.discount_rate ?? 0;
        const startDate = new Date(discount.discount_start_date || discount.discountStartDate || "");
        const endDate = new Date(discount.discount_end_date || discount.discountEndDate || "");
        discountMap.set(ingredientId, { rate, startDate, endDate });
      }
    }
  
    return ingredients.map((ingredient) => {
      const ingredientId = ingredient.ingredient_id || ingredient.ingredientId;
      const ingredientName = ingredient.ingredient_name || ingredient.ingredientName;
      const seasonStartMonth = ingredient.season_start_month ?? ingredient.seasonStartMonth;
      const seasonEndMonth = ingredient.season_end_month ?? ingredient.seasonEndMonth;
      const basePriorityScore = ingredient.base_priority_score ?? ingredient.basePriorityScore ?? 0;
  
      let priorityScore = 0;
      let isInSeason = false;
  
      if (seasonStartMonth !== undefined && seasonEndMonth !== undefined) {
        if (seasonStartMonth <= seasonEndMonth) {
          isInSeason = currentMonth >= seasonStartMonth && currentMonth <= seasonEndMonth;
        } else {
          isInSeason = currentMonth >= seasonStartMonth || currentMonth <= seasonEndMonth;
        }
      }
  
      if (isInSeason) {
        priorityScore = basePriorityScore;
  
        const discount = discountMap.get(ingredientId);
        if (discount) {
          const isWithinDiscountPeriod =
            currentDate >= discount.startDate && currentDate <= discount.endDate;
          if (isWithinDiscountPeriod && discount.rate > 0) {
            priorityScore = Math.round(basePriorityScore * (1 + discount.rate));
          }
        }
      }
  
      return {
        ingredient_id: ingredientId,
        ingredient_name: ingredientName,
        priority_score: priorityScore,
      };
    });
  }
  return { calculateIngredientsSeasonalPriorityScores };
})();
