    const rangeWidth = criteria.maxValue - criteria.minValue;
    const targetPosition = criteria.targetValue - criteria.minValue;
    
    let achievementRate = 100;
    if (rangeWidth > 0) {
      achievementRate = Math.round((targetPosition / rangeWidth) * 100);
    }
  
    // Ensure achievementRate is capped at 100
    achievementRate = Math.min(achievementRate, 100);
  
    // All validations passed
