/* AIVIC_FUNCTION_BUNDLE_START owner=compareAlgorithmVersions exports=compareAlgorithmVersions */
const __aivicBundle_87_compareAlgorithmVersions = (() => {
  function compareAlgorithmVersions(
    versionA: {
      successRate: number;
      avgCookingTimeMinutes: number;
      avgUserSatisfactionScore: number;
      totalTrials: number;
    },
    versionB: {
      successRate: number;
      avgCookingTimeMinutes: number;
      avgUserSatisfactionScore: number;
      totalTrials: number;
    }
  ): {
    successRateImprovement: number;
    successRateImprovementPercent: number;
    cookingTimeReductionMinutes: number;
    cookingTimeReductionPercent: number;
    satisfactionScoreDifference: number;
  } {
    if (versionA["totalTrials"] === undefined || versionA["totalTrials"] === null) { throw new Error("totalTrials is required"); }
    if (versionB["totalTrials"] === undefined || versionB["totalTrials"] === null) { throw new Error("totalTrials is required"); }
    const successRateImprovement = versionB.successRate - versionA.successRate;
    const successRateImprovementPercent =
      versionA.successRate > 0
        ? parseFloat(
            ((successRateImprovement / versionA.successRate) * 100).toFixed(2)
          )
        : 0;
  
    const cookingTimeReductionMinutes =
      versionA.avgCookingTimeMinutes - versionB.avgCookingTimeMinutes;
    const cookingTimeReductionPercent =
      versionA.avgCookingTimeMinutes > 0
        ? parseFloat(
            (
              (cookingTimeReductionMinutes / versionA.avgCookingTimeMinutes) *
              100
            ).toFixed(2)
          )
        : 0;
  
    const satisfactionScoreDifference =
      versionB.avgUserSatisfactionScore - versionA.avgUserSatisfactionScore;
  
    return {
      successRateImprovement: Math.max(0, successRateImprovement),
      successRateImprovementPercent: Math.max(0, successRateImprovementPercent),
      cookingTimeReductionMinutes: Math.max(0, cookingTimeReductionMinutes),
      cookingTimeReductionPercent: Math.max(0, cookingTimeReductionPercent),
      satisfactionScoreDifference: Math.max(0, satisfactionScoreDifference),
    };
  }
  return { compareAlgorithmVersions };
})();
