/* AIVIC_FUNCTION_BUNDLE_START owner=compareAlgorithmImprovementEffects exports=compareAlgorithmImprovementEffects */
const __aivicBundle_88_compareAlgorithmImprovementEffects = (() => {
  function compareAlgorithmImprovementEffects(input: {
    beforeVersionId: string;
    afterVersionId: string;
    beforeVersionMetrics: {
      successRate: number;
      satisfactionScore: number;
      cookingTime: number;
    } | null;
    afterVersionMetrics: {
      successRate: number;
      satisfactionScore: number;
      cookingTime: number;
    } | null;
  }): {
    successRateDelta: number;
    satisfactionDelta: number;
    cookingTimeDelta: number;
    overallImprovementScore: number;
  } {
    if (input["beforeVersionId"] === undefined || input["beforeVersionId"] === null) { throw new Error("beforeVersionId is required"); }
    if (input["afterVersionId"] === undefined || input["afterVersionId"] === null) { throw new Error("afterVersionId is required"); }
    if (!input.beforeVersionMetrics || !input.afterVersionMetrics) {
      throw new Error("バージョンデータが不足しています");
    }
  
    const beforeMetrics = input.beforeVersionMetrics;
    const afterMetrics = input.afterVersionMetrics;
  
    const successRateDelta = afterMetrics.successRate - beforeMetrics.successRate;
    const satisfactionDelta =
      afterMetrics.satisfactionScore - beforeMetrics.satisfactionScore;
    const cookingTimeDelta =
      afterMetrics.cookingTime - beforeMetrics.cookingTime;
  
    const normalizedSuccessRateDelta = Math.min(100, Math.max(-100, successRateDelta));
    const normalizedSatisfactionDelta = Math.min(5, Math.max(-5, satisfactionDelta));
    const normalizedCookingTimeDelta = Math.min(100, Math.max(-100, cookingTimeDelta));
  
    const successRateWeight = 0.4;
    const satisfactionWeight = 0.35;
    const cookingTimeWeight = 0.25;
  
    const successRateContribution =
      (normalizedSuccessRateDelta / 100) * successRateWeight * 100;
    const satisfactionContribution =
      (normalizedSatisfactionDelta / 5) * satisfactionWeight * 100;
    const cookingTimeContribution =
      (-normalizedCookingTimeDelta / 100) * cookingTimeWeight * 100;
  
    const overallImprovementScore = Math.max(
      0,
      Math.min(
        100,
        successRateContribution + satisfactionContribution + cookingTimeContribution
      )
    );
  
    return {
      successRateDelta,
      satisfactionDelta,
      cookingTimeDelta,
      overallImprovementScore,
    };
  }
  return { compareAlgorithmImprovementEffects };
})();
export const compareAlgorithmImprovementEffects = __aivicBundle_88_compareAlgorithmImprovementEffects.compareAlgorithmImprovementEffects;
