/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmImprovementEffect exports=calculateAlgorithmImprovementEffect */
const __aivicBundle_89_calculateAlgorithmImprovementEffect = (() => {
  function calculateAlgorithmImprovementEffect(input: {
    preAlgorithmScore: number;
    postAlgorithmScore: number;
  }): {
    improvementPercentage: number;
    status: string;
    hasError: boolean;
    errorMessage: null | string;
  } {
    const { preAlgorithmScore, postAlgorithmScore } = input;
  
    if (
      preAlgorithmScore === undefined ||
      postAlgorithmScore === undefined ||
      typeof preAlgorithmScore !== 'number' ||
      typeof postAlgorithmScore !== 'number'
    ) {
      return {
        improvementPercentage: 0,
        status: 'エラー',
        hasError: true,
        errorMessage: 'スコアが不正です',
      };
    }
  
    if (preAlgorithmScore === 0) {
      return {
        improvementPercentage: 0,
        status: 'エラー',
        hasError: true,
        errorMessage: '改善前スコアが0です',
      };
    }
  
    const improvementPercentage =
      ((postAlgorithmScore - preAlgorithmScore) / preAlgorithmScore) * 100;
  
    const roundedImprovement = Math.round(improvementPercentage * 10) / 10;
  
    if (roundedImprovement === 0) {
      return {
        improvementPercentage: 0,
        status: '改善なし',
        hasError: false,
        errorMessage: null,
      };
    }
  
    if (roundedImprovement > 0) {
      return {
        improvementPercentage: roundedImprovement,
        status: '改善あり',
        hasError: false,
        errorMessage: null,
      };
    }
  
    return {
      improvementPercentage: roundedImprovement,
      status: '悪化',
      hasError: false,
      errorMessage: null,
    };
  }
  return { calculateAlgorithmImprovementEffect };
})();
