/* AIVIC_FUNCTION_BUNDLE_START owner=notifyDevelopmentTeamOnImprovementProposal exports=notifyDevelopmentTeamOnImprovementProposal */
const __aivicBundle_91_notifyDevelopmentTeamOnImprovementProposal = (() => {
  function notifyDevelopmentTeamOnImprovementProposal(
    proposal: {
      proposalId: string;
      title?: string;
      description?: string;
      proposedBy?: string;
      createdAt?: Date;
      status?: string;
      priority: 'high' | 'medium' | 'low';
      proposalContent?: string;
      affectedUserCount?: number;
      estimatedImplementationDays?: number;
    },
    notificationSettings: {
      developmentTeamMembers?: string[];
      notificationChannels?: string[];
      priority?: string;
    } | 'immediate' | 'weekly' | 'biweekly'
  ): {
    notificationSent: boolean;
    recommendedSprintSlot: 'current' | 'next' | 'backlog';
    impactScore: number;
    developmentTeamAssignee: string | null;
  } {
    if (proposal["proposalId"] === undefined || proposal["proposalId"] === null) { throw new Error("proposalId is required"); }
    // Handle legacy signature: second arg as schedule string
    let teamMembers: string[] = [];
    let notificationChannels: string[] = [];
    
    if (typeof notificationSettings === 'string') {
      // Legacy: notificationSchedule parameter
      teamMembers = ['dev_team_001'];
      notificationChannels = ['email'];
    } else if (notificationSettings && typeof notificationSettings === 'object') {
      teamMembers = notificationSettings.developmentTeamMembers || [];
      notificationChannels = notificationSettings.notificationChannels || [];
    }
  
    // Validate: development team members must be set
    if (teamMembers.length === 0) {
      throw new Error('通知先メンバーが設定されていません');
    }
  
    // Extract priority level
    const priorityLevel = proposal.priority || 'medium';
    
    // Extract affected user count and implementation days
    const affectedUserCount = proposal.affectedUserCount || 0;
    const estimatedImplementationDays = proposal.estimatedImplementationDays || 5;
  
    // Calculate impact score (0-100)
    // Priority weight: high=40, medium=25, low=10
    // Affected users: 0.1 per user (capped at 30)
    // Implementation speed: faster = higher score (capped at 30)
    let priorityScore = 0;
    if (priorityLevel === 'high') {
      priorityScore = 40;
    } else if (priorityLevel === 'medium') {
      priorityScore = 25;
    } else {
      priorityScore = 10;
    }
  
    const userImpactScore = Math.min(affectedUserCount * 0.1, 30);
    const implementationSpeedScore = Math.max(30 - (estimatedImplementationDays * 2), 0);
  
    const impactScore = Math.round(priorityScore + userImpactScore + implementationSpeedScore);
  
    // Determine recommended sprint slot based on impact score
    let recommendedSprintSlot: 'current' | 'next' | 'backlog';
    if (impactScore >= 70) {
      recommendedSprintSlot = 'current';
    } else if (impactScore >= 50) {
      recommendedSprintSlot = 'next';
    } else {
      recommendedSprintSlot = 'backlog';
    }
  
    // Assign development team member (first available or null if none)
    const developmentTeamAssignee = teamMembers.length > 0 ? teamMembers[0] : null;
  
    return {
      notificationSent: false,
      recommendedSprintSlot,
      impactScore,
      developmentTeamAssignee,
    };
  }
  return { notifyDevelopmentTeamOnImprovementProposal };
})();
