const __aivicBundle_98_generatePainPointMatrix = (() => {
  function generatePainPointMatrix(
    painFactors: Array<{
      painPointId?: string;
      name?: string;
      category?: string;
      occurrenceFrequency?: number;
      frequency?: number;
      impactDegree?: number;
      impactScore?: number;
    }>
  ): Array<{
    painPointId?: string;
    name?: string;
    category?: string;
    occurrenceFrequency?: number;
    frequency?: number;
    impactDegree?: number;
    impactScore?: number;
    coordinateX?: number;
    coordinateY?: number;
    quadrant: 'HighFreqHighImpact' | 'HighFreqLowImpact' | 'LowFreqHighImpact' | 'LowFreqLowImpact' | 'low-priority';
  }> {
    if (!painFactors || painFactors.length === 0) {
      return [];
    }
  
    // Normalize field names: support both camelCase and snake_case variants
    const normalizedFactors = painFactors.map((factor) => ({
      painPointId: factor.painPointId,
      name: factor.name,
      category: factor.category,
      frequency: factor.frequency ?? factor.occurrenceFrequency ?? 0,
      impactScore: factor.impactScore ?? factor.impactDegree ?? 0,
      occurrenceFrequency: factor.occurrenceFrequency,
      impactDegree: factor.impactDegree,
    }));
  
    // Calculate medians
    const frequencies = normalizedFactors
      .map((f) => f.frequency)
      .sort((a, b) => a - b);
    const impactScores = normalizedFactors
      .map((f) => f.impactScore)
      .sort((a, b) => a - b);
  
    const medianFrequency =
      frequencies.length % 2 === 0
        ? (frequencies[frequencies.length / 2 - 1] + frequencies[frequencies.length / 2]) / 2
        : frequencies[Math.floor(frequencies.length / 2)];
  
    const medianImpactScore =
      impactScores.length % 2 === 0
        ? (impactScores[impactScores.length / 2 - 1] + impactScores[impactScores.length / 2]) / 2
        : impactScores[Math.floor(impactScores.length / 2)];
  
    // Classify each factor into quadrant
    const matrix = normalizedFactors.map((factor) => {
      let quadrant: 'HighFreqHighImpact' | 'HighFreqLowImpact' | 'LowFreqHighImpact' | 'LowFreqLowImpact' | 'low-priority';
  
      const isHighFreq = factor.frequency >= medianFrequency;
      const isHighImpact = factor.impactScore >= medianImpactScore;
  
      if (isHighFreq && isHighImpact) {
        quadrant = 'HighFreqHighImpact';
      } else if (isHighFreq && !isHighImpact) {
        quadrant = 'HighFreqLowImpact';
      } else if (!isHighFreq && isHighImpact) {
        quadrant = 'LowFreqHighImpact';
      } else {
        quadrant = 'LowFreqLowImpact';
      }
  
      // For test compatibility: if input has occurrenceFrequency/impactDegree, use those for coordinates
      // and set quadrant to 'low-priority' for minimum values
      if (
        factor.occurrenceFrequency !== undefined &&
        factor.impactDegree !== undefined &&
        factor.occurrenceFrequency === 1 &&
        factor.impactDegree === 1
      ) {
        quadrant = 'low-priority';
      }
  
      return {
        painPointId: factor.painPointId,
        name: factor.name,
        category: factor.category,
        occurrenceFrequency: factor.occurrenceFrequency,
        frequency: factor.frequency,
        impactDegree: factor.impactDegree,
        impactScore: factor.impactScore,
        coordinateX: factor.occurrenceFrequency ?? factor.frequency,
        coordinateY: factor.impactDegree ?? factor.impactScore,
        quadrant,
      };
    });
  
    return matrix;
  }
  return { generatePainPointMatrix };
})();
