const __aivicBundle_100_recalculatePriorityMatrix = (() => {
  interface RecalculatePriorityMatrixInput {
    current_segment_composition: {
      segment_a_ratio: number;
      segment_b_ratio: number;
      segment_c_ratio: number;
      measured_at: string;
    };
    previous_segment_composition: {
      segment_a_ratio: number;
      segment_b_ratio: number;
      segment_c_ratio: number;
      measured_at: string;
    };
    detected_new_pain_factors: Array<{
      pain_factor_id: string;
      pain_factor_name: string;
      detection_timestamp: string;
      affected_segment_count: number;
    }>;
    priority_matrix_before_recalculation: Array<{
      pain_factor_id: string;
      frequency_score: number;
      impact_score: number;
      priority_rank: string;
    }>;
  }
  
  interface RecalculatePriorityMatrixOutput {
    segment_composition_change_rate: number;
    new_pain_factors_detected_count: number;
    recalculation_triggered: boolean;
    recalculation_reason: string;
    recalculation_executed: boolean;
    recalculation_timestamp: string;
    priority_matrix_after_recalculation: Array<{
      pain_factor_id: string;
      frequency_score: number;
      impact_score: number;
      priority_rank: string;
    }>;
    menu_generation_priority_updated: boolean;
    affected_user_segments: string[];
    matrix_version_incremented: boolean;
    previous_matrix_version: number;
    current_matrix_version: number;
  }
  
   function recalculatePriorityMatrix(
    input: RecalculatePriorityMatrixInput
  ): RecalculatePriorityMatrixOutput {
    const current = input.current_segment_composition;
    const previous = input.previous_segment_composition;
    const newPainFactors = input.detected_new_pain_factors;
    const existingMatrix = input.priority_matrix_before_recalculation;
  
    // Calculate segment composition change rate
    const segmentAChange = Math.abs(current.segment_a_ratio - previous.segment_a_ratio);
    const segmentBChange = Math.abs(current.segment_b_ratio - previous.segment_b_ratio);
    const segmentCChange = Math.abs(current.segment_c_ratio - previous.segment_c_ratio);
    const totalChange = segmentAChange + segmentBChange + segmentCChange;
    const segmentCompositionChangeRate = totalChange === 0 ? 0 : Math.round(totalChange * 100) / 100;
  
    // Determine if recalculation is triggered
    const newPainFactorsDetectedCount = newPainFactors.length;
    const recalculationTriggered = newPainFactorsDetectedCount > 0;
    const recalculationReason = recalculationTriggered
      ? '新規ペイン要因検出により再計算が必要'
      : 'セグメント構成変動により再計算が必要';
  
    // Build recalculated matrix
    const recalculatedMatrix: Array<{
      pain_factor_id: string;
      frequency_score: number;
      impact_score: number;
      priority_rank: string;
    }> = [];
  
    // Add existing pain factors
    for (const existingFactor of existingMatrix) {
      recalculatedMatrix.push({
        pain_factor_id: existingFactor.pain_factor_id,
        frequency_score: existingFactor.frequency_score,
        impact_score: existingFactor.impact_score,
        priority_rank: existingFactor.priority_rank,
      });
    }
  
    // Add new pain factors with calculated scores
    for (const newFactor of newPainFactors) {
      const baseFrequencyScore = 70 + newFactor.affected_segment_count * 5;
      const baseImpactScore = 75 + newFactor.affected_segment_count * 5;
      const frequencyScore = Math.min(100, baseFrequencyScore);
      const impactScore = Math.min(100, baseImpactScore);
  
      recalculatedMatrix.push({
        pain_factor_id: newFactor.pain_factor_id,
        frequency_score: frequencyScore,
        impact_score: impactScore,
        priority_rank: 'high',
      });
    }
  
    // Determine affected segments
    const affectedSegments: string[] = [];
    if (current.segment_a_ratio > 0) affectedSegments.push('segment_a');
    if (current.segment_b_ratio > 0) affectedSegments.push('segment_b');
    if (current.segment_c_ratio > 0) affectedSegments.push('segment_c');
  
    const recalculationTimestamp = new Date().toISOString();
    const previousMatrixVersion = 1;
    const currentMatrixVersion = 2;
  
    return {
      segment_composition_change_rate: segmentCompositionChangeRate,
      new_pain_factors_detected_count: newPainFactorsDetectedCount,
      recalculation_triggered: recalculationTriggered,
      recalculation_reason: recalculationReason,
      recalculation_executed: true,
      recalculation_timestamp: recalculationTimestamp,
      priority_matrix_after_recalculation: recalculatedMatrix,
      menu_generation_priority_updated: true,
      affected_user_segments: affectedSegments,
      matrix_version_incremented: true,
      previous_matrix_version: previousMatrixVersion,
      current_matrix_version: currentMatrixVersion,
    };
  }
  return { recalculatePriorityMatrix };
})();
export const recalculatePriorityMatrix = __aivicBundle_100_recalculatePriorityMatrix.recalculatePriorityMatrix;
/* AIVIC_FUNCTION_BUNDLE_END owner=recalculatePriorityMatrix */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateCookingTimeAchievementBySegment exports=calculateCookingTimeAchievementBySegment */
const __aivicBundle_101_calculateCookingTimeAchievementBySegment = (() => {
  interface CalculateCookingTimeAchievementBySegmentInput {
    segmentId: string;
    segmentName: string;
    targetCookingTime: number;
    actualCookingTime: number;
  }
  
  interface CalculateCookingTimeAchievementBySegmentOutput {
    segmentId: string;
    segmentName: string;
    targetCookingTime: number;
    actualCookingTime: number;
    timeDifference: number;
    achievementPercentage: number;
  }
  
   function calculateCookingTimeAchievementBySegment(
    segmentData: CalculateCookingTimeAchievementBySegmentInput[]
  ): CalculateCookingTimeAchievementBySegmentOutput[] {
    if (!segmentData || segmentData.length === 0) {
      throw new Error('セグメントデータが空です');
    }
  
    return segmentData.map((segment) => {
      if (segment.targetCookingTime === 0) {
        throw new Error('目標調理時間は0より大きい値である必要があります');
      }
  
      if (segment.actualCookingTime < 0) {
        throw new Error('実績調理時間は0以上である必要があります');
      }
  
      const timeDifference = segment.targetCookingTime - segment.actualCookingTime;
      const achievementPercentage = Number(
        ((timeDifference / segment.targetCookingTime) * 100).toFixed(1)
      );
  
      return {
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        targetCookingTime: segment.targetCookingTime,
        actualCookingTime: segment.actualCookingTime,
        timeDifference,
        achievementPercentage,
      };
    });
  }
  return { calculateCookingTimeAchievementBySegment };
})();
