/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeSegmentsByDifferentiationEffect exports=prioritizeSegmentsByDifferentiationEffect */
const __aivicBundle_103_prioritizeSegmentsByDifferentiationEffect = (() => {
  function prioritizeSegmentsByDifferentiationEffect(
    segments: Array<{
      segmentId: string;
      segmentName?: string;
      improvementEffect?: number;
      occurrenceFrequency?: number;
      successRate?: number;
      cookingTimeReduction?: number;
      satisfactionScore?: number;
    }>
  ): Array<{
    segmentId: string;
    segmentName?: string;
    improvementEffect?: number;
    occurrenceFrequency?: number;
    successRate?: number;
    cookingTimeReduction?: number;
    satisfactionScore?: number;
    differentiationScore?: number;
    priority: number;
  }> {
    if (!segments || segments.length === 0) {
      return [];
    }
  
    const scoredSegments = segments.map((segment) => {
      let differentiationScore: number;
  
      if (
        segment.successRate !== undefined &&
        segment.cookingTimeReduction !== undefined &&
        segment.satisfactionScore !== undefined
      ) {
        differentiationScore =
          segment.successRate * 0.25 +
          segment.cookingTimeReduction * 0.25 +
          segment.satisfactionScore * 0.5;
      } else if (segment.improvementEffect !== undefined) {
        differentiationScore = segment.improvementEffect;
      } else {
        differentiationScore = 0;
      }
  
      return {
        ...segment,
        differentiationScore,
      };
    });
  
    const sortedSegments = scoredSegments.sort((a, b) => {
      const scoreDiff = (b.differentiationScore || 0) - (a.differentiationScore || 0);
      if (scoreDiff !== 0) {
        return scoreDiff;
      }
  
      const freqA = a.occurrenceFrequency || 0;
      const freqB = b.occurrenceFrequency || 0;
      return freqB - freqA;
    });
  
    return sortedSegments.map((segment, index) => ({
      ...segment,
      priority: index + 1,
    }));
  }
  return { prioritizeSegmentsByDifferentiationEffect };
})();
export const prioritizeSegmentsByDifferentiationEffect = __aivicBundle_103_prioritizeSegmentsByDifferentiationEffect.prioritizeSegmentsByDifferentiationEffect;
/* AIVIC_FUNCTION_BUNDLE_END owner=prioritizeSegmentsByDifferentiationEffect */

