const __aivicBundle_104_assignPrioritiesToDifferentiationFeatures = (() => {
  interface AssignPrioritiesToDifferentiationFeaturesInput {
    segmentAnalysisData: {
      segments: Array<{
        segmentId: string;
        segmentName: string;
        userCount: number;
        mealtimePreferenceScore: number;
        budgetSensitivity: number;
        nutritionFocusScore: number;
        mealPlanAcceptanceRate: number;
        cookingTimeReductionAchievement: number;
        userSatisfactionScore: number;
        featureUsageFrequency: Record<string, number>;
        sessionDurationMinutes: number;
        conversionRate: number;
        churnRate: number;
      }>;
      analysisDate: string;
    };
    differentiationFeatureCandidates: Array<{
      featureId: string;
      featureName: string;
      estimatedImplementationDifficulty: number;
      expectedROIPercentage: number;
      targetSegmentIds: string[];
    }>;
  }
  
  interface PrioritizedFeature {
    featureName: string;
    priorityScore: number;
    priorityRank: number;
    targetSegmentAllocation: {
      primarySegment: string;
      secondarySegments: string[];
    };
  }
  
  interface PhaseRolloutPlan {
    phaseName: string;
    allocatedPercentage: number;
    targetedFeatures: string[];
  }
  
  interface AllocationStrategy {
    totalAllocatedResources: number;
    phaseRolloutPlan: PhaseRolloutPlan[];
  }
  
  interface PrioritizationLogic {
    roiWeightage: number;
    implementationDifficultyWeightage: number;
    segmentCoverageWeightage: number;
  }
  
  interface AssignPrioritiesToDifferentiationFeaturesOutput {
    prioritizedFeatures: PrioritizedFeature[];
    allocationStrategy: AllocationStrategy;
    prioritizationLogic: PrioritizationLogic;
    generatedAt: string;
  }
  
   function assignPrioritiesToDifferentiationFeatures(
    input: AssignPrioritiesToDifferentiationFeaturesInput
  ): AssignPrioritiesToDifferentiationFeaturesOutput {
    const { segmentAnalysisData, differentiationFeatureCandidates } = input;
  
    const ROI_WEIGHTAGE = 0.4;
    const IMPLEMENTATION_DIFFICULTY_WEIGHTAGE = 0.3;
    const SEGMENT_COVERAGE_WEIGHTAGE = 0.3;
  
    const featureScores = differentiationFeatureCandidates.map((feature) => {
      const segmentCoverageScore =
        (feature.targetSegmentIds.length / segmentAnalysisData.segments.length) *
        100;
  
      const implementationDifficultyScore = 100 - feature.estimatedImplementationDifficulty;
  
      const priorityScore = Math.round(
        feature.expectedROIPercentage * ROI_WEIGHTAGE +
          implementationDifficultyScore * IMPLEMENTATION_DIFFICULTY_WEIGHTAGE +
          segmentCoverageScore * SEGMENT_COVERAGE_WEIGHTAGE
      );
  
      const primarySegmentId = feature.targetSegmentIds[0];
      const primarySegment = segmentAnalysisData.segments.find(
        (s) => s.segmentId === primarySegmentId
      );
  
      const secondarySegmentIds = feature.targetSegmentIds.slice(1);
  
      const targetSegmentAllocation = {
        primarySegment: primarySegmentId,
        secondarySegments: secondarySegmentIds,
      };
  
      return {
        featureName: feature.featureName,
        priorityScore,
        targetSegmentAllocation,
        originalIndex: differentiationFeatureCandidates.indexOf(feature),
      };
    });
  
    featureScores.sort((a, b) => b.priorityScore - a.priorityScore);
  
    const prioritizedFeatures: PrioritizedFeature[] = featureScores.map(
      (score, index) => ({
        featureName: score.featureName,
        priorityScore: score.priorityScore,
        priorityRank: index + 1,
        targetSegmentAllocation: score.targetSegmentAllocation,
      })
    );
  
    const phaseRolloutPlan: PhaseRolloutPlan[] = [
      {
        phaseName: 'Phase 1',
        allocatedPercentage: 40,
        targetedFeatures: [prioritizedFeatures[0].featureName],
      },
      {
        phaseName: 'Phase 2',
        allocatedPercentage: 35,
        targetedFeatures: [prioritizedFeatures[1].featureName],
      },
      {
        phaseName: 'Phase 3',
        allocatedPercentage: 25,
        targetedFeatures: prioritizedFeatures
          .slice(2)
          .map((f) => f.featureName),
      },
    ];
  
    const allocationStrategy: AllocationStrategy = {
      totalAllocatedResources: 100,
      phaseRolloutPlan,
    };
  
    const prioritizationLogic: PrioritizationLogic = {
      roiWeightage: ROI_WEIGHTAGE,
      implementationDifficultyWeightage: IMPLEMENTATION_DIFFICULTY_WEIGHTAGE,
      segmentCoverageWeightage: SEGMENT_COVERAGE_WEIGHTAGE,
    };
  
    const generatedAt = new Date().toISOString();
  
    return {
      prioritizedFeatures,
      allocationStrategy,
      prioritizationLogic,
      generatedAt,
    };
  }
  return { assignPrioritiesToDifferentiationFeatures };
})();
export const assignPrioritiesToDifferentiationFeatures = __aivicBundle_104_assignPrioritiesToDifferentiationFeatures.assignPrioritiesToDifferentiationFeatures;
/* AIVIC_FUNCTION_BUNDLE_END owner=assignPrioritiesToDifferentiationFeatures */

/* AIVIC_FUNCTION_BUNDLE_START owner=assignPriorityWithPainQuantification exports=assignPriorityWithPainQuantification */
const __aivicBundle_105_assignPriorityWithPainQuantification = (() => {
  function assignPriorityWithPainQuantification(input: any): any {
    // Validation: Check for required fields
    const requiredFields = [
      'userCount',
      'impactScore',
      'resolutionTimeMinutes',
      'segmentAffectedCount',
      'satisfactionGainScore',
      'painCategoryId',
      'painCategoryName',
      'detectionFrequency',
      'implementationDifficulty',
    ];
  
    const missingFields: string[] = [];
    for (const field of requiredFields) {
      if (input[field] === undefined || input[field] === null) {
        missingFields.push(field);
      }
    }
  
    if (missingFields.length > 0) {
      throw new Error(`必須項目が不足しています: ${missingFields.join(', ')}`);
    }
  
    // Validation: userCount must be > 0
    if (typeof input.userCount !== 'number' || input.userCount <= 0) {
      throw new Error('ユーザー数は0より大きい値である必要があります');
    }
  
    // Validation: impactScore must be 0-100
    if (
      typeof input.impactScore !== 'number' ||
      input.impactScore < 0 ||
      input.impactScore > 100
    ) {
      throw new Error('影響度は0から100の範囲である必要があります');
    }
  
    // Validation: satisfactionGainScore must be 0-100
    if (
      typeof input.satisfactionGainScore !== 'number' ||
      input.satisfactionGainScore < 0 ||
      input.satisfactionGainScore > 100
    ) {
      throw new Error('満足度は0から100の範囲である必要があります');
    }
  
    // Validation: implementationDifficulty must be 1-5
    if (
      typeof input.implementationDifficulty !== 'number' ||
      input.implementationDifficulty < 1 ||
      input.implementationDifficulty > 5
    ) {
      throw new Error('実装難度は1から5の範囲である必要があります');
    }
  
    // Validation: detectionFrequency must be > 0
    if (
      typeof input.detectionFrequency !== 'number' ||
      input.detectionFrequency <= 0
    ) {
      throw new Error('検出頻度は0より大きい値である必要があります');
    }
  
    // Validation: resolutionTimeMinutes must be >= 0
    if (
      typeof input.resolutionTimeMinutes !== 'number' ||
      input.resolutionTimeMinutes < 0
    ) {
      throw new Error('時間は0以上である必要があります');
    }
  
    // Calculate priority score
    // Formula: (userCount / 100) * impactScore * satisfactionGainScore * detectionFrequency / (implementationDifficulty * resolutionTimeMinutes / 100 + 1)
    const userCountFactor = input.userCount / 100;
    const impactFactor = input.impactScore / 100;
    const satisfactionFactor = input.satisfactionGainScore / 100;
    const difficultyPenalty = input.implementationDifficulty / 5;
    const timePenalty = Math.max(1, input.resolutionTimeMinutes / 100);
  
    const priorityScore =
      (userCountFactor *
        impactFactor *
        satisfactionFactor *
        input.detectionFrequency) /
      (difficultyPenalty * timePenalty);
  
    // Round to 2 decimal places
    const roundedPriorityScore = Math.round(priorityScore * 100) / 100;
  
    // Determine priority rank based on score
    let priorityRank: string;
    if (roundedPriorityScore >= 75) {
      priorityRank = 'CRITICAL';
    } else if (roundedPriorityScore >= 50) {
      priorityRank = 'HIGH';
    } else if (roundedPriorityScore >= 30) {
      priorityRank = 'MEDIUM';
    } else {
      priorityRank = 'LOW';
    }
  
    return {
      priorityScore: roundedPriorityScore,
      priorityRank,
      painCategoryId: input.painCategoryId,
      painCategoryName: input.painCategoryName,
    };
  }
  return { assignPriorityWithPainQuantification };
})();
export const assignPriorityWithPainQuantification = __aivicBundle_105_assignPriorityWithPainQuantification.assignPriorityWithPainQuantification;
/* AIVIC_FUNCTION_BUNDLE_END owner=assignPriorityWithPainQuantification */

/* AIVIC_FUNCTION_BUNDLE_START owner=assignPriorityToSegments exports=assignPriorityToSegments */
const __aivicBundle_106_assignPriorityToSegments = (() => {
  function assignPriorityToSegments(
    segments: Array<{
      id: string;
      name: string;
      priority_score: number;
    }>
  ): Array<{
    id: string;
    name: string;
    priority_score: number;
    assigned_priority_rank: number;
  }> {
    if (!segments || segments.length === 0) {
      return [];
    }
  
    // Sort by priority_score descending, then maintain input order for ties
    const sortedWithIndex = segments.map((seg, index) => ({
      ...seg,
      originalIndex: index,
    }));
  
    sortedWithIndex.sort((a, b) => {
      const scoreDiff = b.priority_score - a.priority_score;
      if (scoreDiff !== 0) {
        return scoreDiff;
      }
      // For equal scores, maintain original input order
      return a.originalIndex - b.originalIndex;
    });
  
    // Assign ranks based on sorted order
    const result = sortedWithIndex.map((seg, rank) => ({
      id: seg.id,
      name: seg.name,
      priority_score: seg.priority_score,
      assigned_priority_rank: rank + 1,
    }));
  
    return result;
  }
  return { assignPriorityToSegments };
})();
export const assignPriorityToSegments = __aivicBundle_106_assignPriorityToSegments.assignPriorityToSegments;
/* AIVIC_FUNCTION_BUNDLE_END owner=assignPriorityToSegments */

