/* AIVIC_FUNCTION_BUNDLE_START owner=detectOutliersAndValidateQuality exports=detectOutliersAndValidateQuality */
const __aivicBundle_109_detectOutliersAndValidateQuality = (() => {
  function detectOutliersAndValidateQuality(evaluationRecords: any[]): any {
    const detectionLog: string[] = [];
    const detectedOutliers: any[] = [];
    const retainedIndicators: any[] = [];
    const excludedIndicators: any[] = [];
  
    // Define valid ranges for behavioral indicators
    const COOKING_TIME_MIN = 15;
    const COOKING_TIME_MAX = 120;
    const NUTRITION_SCORE_MIN = 0;
    const NUTRITION_SCORE_MAX = 100;
    const SATISFACTION_SCORE_MIN = 1;
    const SATISFACTION_SCORE_MAX = 5;
    const COMPLETION_RATE_MIN = 0;
    const COMPLETION_RATE_MAX = 1;
  
    // Process each record
    evaluationRecords.forEach((record: any, index: number) => {
      const reasons: string[] = [];
      let isOutlier = false;
  
      // Check cookingTimeMinutes
      if (
        record.cookingTimeMinutes !== undefined &&
        (record.cookingTimeMinutes < COOKING_TIME_MIN ||
          record.cookingTimeMinutes > COOKING_TIME_MAX)
      ) {
        reasons.push('cookingTimeMinutes_exceeds_threshold');
        isOutlier = true;
      }
  
      // Check nutritionScorePoints
      if (record.nutritionScorePoints !== undefined) {
        if (record.nutritionScorePoints < NUTRITION_SCORE_MIN) {
          reasons.push('nutritionScorePoints_negative_value');
          isOutlier = true;
        } else if (record.nutritionScorePoints > NUTRITION_SCORE_MAX) {
          reasons.push('nutritionScorePoints_exceeds_maximum');
          isOutlier = true;
        }
      }
  
      // Check satisfactionScore
      if (
        record.satisfactionScore !== undefined &&
        (record.satisfactionScore < SATISFACTION_SCORE_MIN ||
          record.satisfactionScore > SATISFACTION_SCORE_MAX)
      ) {
        reasons.push('satisfactionScore_out_of_range');
        isOutlier = true;
      }
  
      // Check completionRate
      if (
        record.completionRate !== undefined &&
        (record.completionRate < COMPLETION_RATE_MIN ||
          record.completionRate > COMPLETION_RATE_MAX)
      ) {
        reasons.push('completionRate_out_of_range');
        isOutlier = true;
      }
  
      if (isOutlier) {
        detectedOutliers.push({
          index,
          record,
          reasons,
        });
        excludedIndicators.push(record);
        detectionLog.push(
          `Record at index ${index} detected as outlier: ${reasons.join(', ')}`
        );
      } else {
        retainedIndicators.push(record);
        detectionLog.push(`Record at index ${index} passed validation`);
      }
    });
  
    // Calculate quality metrics
    const totalRecords = evaluationRecords.length;
    const validRecordCount = retainedIndicators.length;
    const outlierRecordCount = detectedOutliers.length;
  
    const completenessRate =
      totalRecords > 0
        ? (evaluationRecords.filter(
            (r: any) =>
              r.cookingTimeMinutes !== undefined &&
              r.nutritionScorePoints !== undefined &&
              r.satisfactionScore !== undefined &&
              r.completionRate !== undefined
          ).length /
            totalRecords) *
          100
        : 0;
  
    const consistencyRate =
      totalRecords > 0 ? (validRecordCount / totalRecords) * 100 : 0;
  
    const accuracyRate = consistencyRate;
  
    const dataQualityScore =
      totalRecords > 0 ? (validRecordCount / totalRecords) * 100 : 100;
  
    const qualityMetrics: any = {
      dataQualityScore,
      completenessRate,
      consistencyRate,
      accuracyRate,
      passedValidation: outlierRecordCount === 0,
    };
  
    const isValid = outlierRecordCount === 0;
  
    const report = {
      totalRecords,
      validRecords: validRecordCount,
      outlierRecords: outlierRecordCount,
      generatedAt: new Date().toISOString(),
    };
  
    return {
      isValid,
      detectedOutliers,
      retainedIndicators,
      excludedIndicators,
      qualityScore: dataQualityScore,
      qualityMetrics,
      report,
      detectionLog,
    };
  }
  return { detectOutliersAndValidateQuality };
})();
export const detectOutliersAndValidateQuality = __aivicBundle_109_detectOutliersAndValidateQuality.detectOutliersAndValidateQuality;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectOutliersAndValidateQuality */

