const __aivicBundle_110_detectAnomaliesWithFallback = (() => {
  function detectAnomaliesWithFallback(
    input: any,
    anomalyThresholds?: { stdDevMultiplier: number; emptyFieldAllowed: boolean },
    cachedPastData?: any[]
  ): {
    validRecords: any[];
    anomalousRecords: any[];
    usedFallback: boolean;
    fallbackReason: string | null;
  } {
    // Handle input shape: either direct array or object with utilizationLogs
    let dataRecords: any[] = [];
    let mealCandidates: any[] = [];
    let qualityThreshold: number = 0.7;
  
    if (Array.isArray(input)) {
      dataRecords = input;
    } else if (input && typeof input === "object") {
      dataRecords = input.utilizationLogs || [];
      mealCandidates = input.mealCandidates || [];
      qualityThreshold = input.qualityThreshold ?? 0.7;
    }
  
    // Validate required data
    if (!Array.isArray(dataRecords)) {
      throw new Error("利用ログが無効な形式です");
    }
  
    if (dataRecords.length === 0 && (!mealCandidates || mealCandidates.length === 0)) {
      throw new Error("利用ログが欠落しています");
    }
  
    const thresholds = anomalyThresholds || {
      stdDevMultiplier: 2,
      emptyFieldAllowed: false,
    };
  
    // If no data records, use fallback
    if (dataRecords.length === 0) {
      const fallbackReason =
        "外部データが不足しているため、キャッシュされた過去データから平均値を算出";
  
      if (!cachedPastData || cachedPastData.length === 0) {
        return {
          validRecords: [],
          anomalousRecords: [],
          usedFallback: true,
          fallbackReason,
        };
      }
  
      // Calculate mean from cached data
      const numericValues = cachedPastData
        .map((record: any) => record.value)
        .filter((v: any) => typeof v === "number");
  
      if (numericValues.length === 0) {
        return {
          validRecords: [],
          anomalousRecords: [],
          usedFallback: true,
          fallbackReason,
        };
      }
  
      const mean = numericValues.reduce((a: number, b: number) => a + b, 0) / numericValues.length;
      const variance =
        numericValues.reduce((sum: number, v: number) => sum + Math.pow(v - mean, 2), 0) /
        numericValues.length;
      const stdDev = Math.sqrt(variance);
      const threshold = mean + thresholds.stdDevMultiplier * stdDev;
  
      return {
        validRecords: cachedPastData.filter((record: any) => record.value <= threshold),
        anomalousRecords: cachedPastData.filter((record: any) => record.value > threshold),
        usedFallback: true,
        fallbackReason,
      };
    }
  
    // Extract numeric values for anomaly detection
    const numericValues = dataRecords
      .map((record: any) => {
        if (typeof record === "number") return record;
        if (record && typeof record === "object") {
          return (
            record.value ??
            record.satisfactionScore ??
            record.completionRate ??
            record.nutritionScore
          );
        }
        return null;
      })
      .filter((v: any) => typeof v === "number");
  
    // If insufficient numeric data, use fallback
    if (numericValues.length < 2) {
      const fallbackReason =
        numericValues.length === 0
          ? "数値データが不足しているため、キャッシュされた過去データから平均値を算出"
          : null;
  
      if (fallbackReason && cachedPastData && cachedPastData.length > 0) {
        const cachedNumeric = cachedPastData
          .map((r: any) => r.value)
          .filter((v: any) => typeof v === "number");
  
        if (cachedNumeric.length > 0) {
          const mean = cachedNumeric.reduce((a: number, b: number) => a + b, 0) / cachedNumeric.length;
          const variance =
            cachedNumeric.reduce((sum: number, v: number) => sum + Math.pow(v - mean, 2), 0) /
            cachedNumeric.length;
          const stdDev = Math.sqrt(variance);
          const threshold = mean + thresholds.stdDevMultiplier * stdDev;
  
          return {
            validRecords: dataRecords.filter((record: any) => {
              const val =
                record.value ??
                record.satisfactionScore ??
                record.completionRate ??
                record.nutritionScore;
              return typeof val === "number" && val <= threshold;
            }),
            anomalousRecords: dataRecords.filter((record: any) => {
              const val =
                record.value ??
                record.satisfactionScore ??
                record.completionRate ??
                record.nutritionScore;
              return typeof val === "number" && val > threshold;
            }),
            usedFallback: true,
            fallbackReason,
          };
        }
      }
    }
  
    // Calculate mean and standard deviation
    const mean = numericValues.reduce((a: number, b: number) => a + b, 0) / numericValues.length;
    const variance =
      numericValues.reduce((sum: number, v: number) => sum + Math.pow(v - mean, 2), 0) /
      numericValues.length;
    const stdDev = Math.sqrt(variance);
  
    // Determine anomaly threshold
    const anomalyThreshold = mean + thresholds.stdDevMultiplier * stdDev;
  
    // Classify records
    const validRecords: any[] = [];
    const anomalousRecords: any[] = [];
  
    dataRecords.forEach((record: any) => {
      let value: number | null = null;
  
      if (typeof record === "number") {
        value = record;
      } else if (record && typeof record === "object") {
        value =
          record.value ??
          record.satisfactionScore ??
          record.completionRate ??
          record.nutritionScore;
      }
  
      if (value === null || typeof value !== "number") {
        if (thresholds.emptyFieldAllowed) {
          validRecords.push(record);
        } else {
          anomalousRecords.push(record);
        }
      } else if (value <= anomalyThreshold) {
        validRecords.push(record);
      } else {
        anomalousRecords.push(record);
      }
    });
  
    return {
      validRecords,
      anomalousRecords,
      usedFallback: false,
      fallbackReason: null,
    };
  }
  return { detectAnomaliesWithFallback };
})();
export const detectAnomaliesWithFallback = __aivicBundle_110_detectAnomaliesWithFallback.detectAnomaliesWithFallback;
