/* AIVIC_FUNCTION_BUNDLE_START owner=detectOutliers exports=detectOutliers */
const __aivicBundle_111_detectOutliers = (() => {
  interface DetectOutliersInput {
    value: number;
    mean: number;
    stdDev: number;
  }
  
  interface DetectOutliersResult {
    isOutlier: boolean;
    value: number;
  }
  
   function detectOutliers(input: DetectOutliersInput): DetectOutliersResult {
    const { value, mean, stdDev } = input;
  
    // Calculate the 3-sigma bounds
    const upperBound = mean + 3 * stdDev;
    const lowerBound = mean - 3 * stdDev;
  
    // Determine if the value is an outlier
    // A value is an outlier if it exceeds the bounds (strictly beyond, not equal)
    const isOutlier = value > upperBound || value < lowerBound;
  
    return {
      isOutlier,
      value,
    };
  }
  return { detectOutliers };
})();
export const detectOutliers = __aivicBundle_111_detectOutliers.detectOutliers;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectOutliers */

