/* AIVIC_FUNCTION_BUNDLE_START owner=validateAndExtractQualityPassedData exports=validateAndExtractQualityPassedData */
const __aivicBundle_113_validateAndExtractQualityPassedData = (() => {
  function validateAndExtractQualityPassedData(
    allRecords: any[],
    qualityThreshold: any
  ): { passedRecords: any[]; failedRecords: any[]; passRate: number; qualityScore: number } {
    // qualityThreshold が関数（エラーハンドラ）の場合、品質検証エラーを発生させる
    if (typeof qualityThreshold === 'function') {
      const failedRecord = allRecords.find(
        (record) => record.qualityVerificationStatus === 'FAILED'
      );
      if (failedRecord) {
        const error = new Error(
          `品質検証不合格: レコード ${failedRecord.id} は品質検証に不合格です`
        );
        qualityThreshold(error);
        throw error;
      }
    }
  
    // qualityThreshold が数値の場合、通常の品質スコア計算処理
    const threshold = typeof qualityThreshold === 'number' ? qualityThreshold : 80;
  
    const passedRecords: any[] = [];
    const failedRecords: any[] = [];
    let totalQualityScore = 0;
  
    for (const record of allRecords) {
      // 品質スコアを計算（完全性・一貫性・精度の加重平均）
      const completenessScore = calculateCompleteness(record);
      const consistencyScore = calculateConsistency(record);
      const accuracyScore = calculateAccuracy(record);
  
      const qualityScore =
        (completenessScore * 0.33 +
          consistencyScore * 0.33 +
          accuracyScore * 0.33) *
        100;
  
      totalQualityScore += qualityScore;
  
      if (qualityScore >= threshold) {
        passedRecords.push(record);
      } else {
        failedRecords.push(record);
      }
    }
  
    const passRate =
      allRecords.length > 0 ? (passedRecords.length / allRecords.length) * 100 : 0;
    const overallQualityScore =
      allRecords.length > 0 ? totalQualityScore / allRecords.length : 0;
  
    return {
      passedRecords,
      failedRecords,
      passRate,
      qualityScore: overallQualityScore
    };
  }
  
  function calculateCompleteness(record: any): number {
    let completenessScore = 0;
    let fieldCount = 0;
  
    const requiredFields = [
      'satisfactionScore',
      'completionRate',
      'qualityVerificationStatus'
    ];
  
    for (const field of requiredFields) {
      fieldCount++;
      if (
        record[field] !== undefined &&
        record[field] !== null &&
        record[field] !== ''
      ) {
        completenessScore++;
      }
    }
  
    return fieldCount > 0 ? completenessScore / fieldCount : 0;
  }
  
  function calculateConsistency(record: any): number {
    let consistencyScore = 0;
  
    // satisfactionScore が有効範囲内か確認
    if (
      typeof record.satisfactionScore === 'number' &&
      record.satisfactionScore >= 1 &&
      record.satisfactionScore <= 5
    ) {
      consistencyScore += 0.5;
    }
  
    // completionRate が有効範囲内か確認
    if (
      typeof record.completionRate === 'number' &&
      record.completionRate >= 0 &&
      record.completionRate <= 100
    ) {
      consistencyScore += 0.5;
    }
  
    return consistencyScore;
  }
  
  function calculateAccuracy(record: any): number {
    let accuracyScore = 0;
  
    // qualityVerificationStatus が有効な値か確認
    if (
      record.qualityVerificationStatus === 'PASSED' ||
      record.qualityVerificationStatus === 'FAILED'
    ) {
      accuracyScore += 0.5;
    }
  
    // verificationNotes が存在するか確認
    if (record.verificationNotes && record.verificationNotes.length > 0) {
      accuracyScore += 0.5;
    }
  
    return accuracyScore;
  }
  return { validateAndExtractQualityPassedData };
})();
