/* AIVIC_FUNCTION_BUNDLE_START owner=extractFilteredMetricsData exports=extractFilteredMetricsData */
const __aivicBundle_114_extractFilteredMetricsData = (() => {
  function extractFilteredMetricsData(
    allMetrics: Array<{
      user_id?: string;
      meal_plan_id?: string;
      cooking_time_reduction_score?: number;
      satisfaction_score?: number;
      completion_rate?: number;
      timestamp?: string;
      successRate?: number;
      cookingTime?: number;
      satisfactionScore?: number;
      date?: string;
    }>,
    filterCriteria: {
      cooking_time_reduction_score?: number;
      minSuccessRate?: number;
      maxCookingTime?: number;
      minSatisfactionScore?: number;
    }
  ): {
    data: Array<{
      user_id?: string;
      meal_plan_id?: string;
      cooking_time_reduction_score?: number;
      satisfaction_score?: number;
      completion_rate?: number;
      timestamp?: string;
      successRate?: number;
      cookingTime?: number;
      satisfactionScore?: number;
      date?: string;
    }>;
    total_count: number;
    successRate?: number;
    averageCookingTime?: number;
    averageSatisfactionScore?: number;
    dataPointCount?: number;
    filterCriteria?: string;
    appliedFilters?: string[];
  } {
    let filteredData = allMetrics;
  
    // Apply cooking_time_reduction_score filter (exact match)
    if (
      filterCriteria.cooking_time_reduction_score !== undefined
    ) {
      filteredData = filteredData.filter(
        (item) =>
          item.cooking_time_reduction_score ===
          filterCriteria.cooking_time_reduction_score
      );
    }
  
    // Apply minSuccessRate filter
    if (filterCriteria.minSuccessRate !== undefined) {
      filteredData = filteredData.filter((item) => {
        const successRate = item.successRate ?? 0;
        return successRate >= filterCriteria.minSuccessRate!;
      });
    }
  
    // Apply maxCookingTime filter
    if (filterCriteria.maxCookingTime !== undefined) {
      filteredData = filteredData.filter((item) => {
        const cookingTime = item.cookingTime ?? 0;
        return cookingTime <= filterCriteria.maxCookingTime!;
      });
    }
  
    // Apply minSatisfactionScore filter
    if (filterCriteria.minSatisfactionScore !== undefined) {
      filteredData = filteredData.filter((item) => {
        const satisfactionScore = item.satisfactionScore ?? 0;
        return satisfactionScore >= filterCriteria.minSatisfactionScore!;
      });
    }
  
    // Calculate averages
    let avgSuccessRate: number | undefined;
    let avgCookingTime: number | undefined;
    let avgSatisfactionScore: number | undefined;
  
    if (filteredData.length > 0) {
      const successRates = filteredData
        .map((item) => item.successRate)
        .filter((val) => val !== undefined) as number[];
      if (successRates.length > 0) {
        avgSuccessRate =
          successRates.reduce((a, b) => a + b, 0) / successRates.length;
      }
  
      const cookingTimes = filteredData
        .map((item) => item.cookingTime)
        .filter((val) => val !== undefined) as number[];
      if (cookingTimes.length > 0) {
        avgCookingTime =
          cookingTimes.reduce((a, b) => a + b, 0) / cookingTimes.length;
      }
  
      const satisfactionScores = filteredData
        .map((item) => item.satisfactionScore)
        .filter((val) => val !== undefined) as number[];
      if (satisfactionScores.length > 0) {
        avgSatisfactionScore =
          satisfactionScores.reduce((a, b) => a + b, 0) /
          satisfactionScores.length;
      }
    }
  
    const appliedFilters: string[] = [];
    if (filterCriteria.cooking_time_reduction_score !== undefined) {
      appliedFilters.push(
        `cooking_time_reduction_score=${filterCriteria.cooking_time_reduction_score}`
      );
    }
    if (filterCriteria.minSuccessRate !== undefined) {
      appliedFilters.push(
        `minSuccessRate=${filterCriteria.minSuccessRate}`
      );
    }
    if (filterCriteria.maxCookingTime !== undefined) {
      appliedFilters.push(`maxCookingTime=${filterCriteria.maxCookingTime}`);
    }
    if (filterCriteria.minSatisfactionScore !== undefined) {
      appliedFilters.push(
        `minSatisfactionScore=${filterCriteria.minSatisfactionScore}`
      );
    }
  
    return {
      data: filteredData,
      total_count: filteredData.length,
      successRate: avgSuccessRate,
      averageCookingTime: avgCookingTime,
      averageSatisfactionScore: avgSatisfactionScore,
      dataPointCount: filteredData.length,
      filterCriteria:
        appliedFilters.length > 0 ? appliedFilters.join("; ") : "none",
      appliedFilters: appliedFilters,
    };
  }
  return { extractFilteredMetricsData };
})();
